print('dumps',time.time()-t,len(data))
def unique(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
def number(text):
    v=float(text)
    if not math.isfinite(v): raise ValueError('nonfinite')
    return v
def invalid(t): raise ValueError('c')
t=time.time()
o=json.loads(data.decode('utf-8'),object_pairs_hook=unique,parse_constant=invalid,parse_float=number)
